"""MkDocs hook generated by codelabgen.

A recording appears in Markdown as an animated GIF, which GitHub shows. On the
site, a GIF with a `.cast` file next to it becomes an interactive asciinema
player, where the text can be selected and copied.
"""

import re
from pathlib import Path

GIF = re.compile(r"!\[([^\]]*)\]\(([^)\s]+)\.gif\)")


def on_page_markdown(markdown, page, **kwargs):
    folder = Path(page.file.abs_src_path).parent

    def replace(match):
        alt, stem = match.group(1), match.group(2)
        if not (folder / f"{stem}.cast").is_file():
            return match.group(0)
        return (
            f'<div class="asciinema-cast" data-src="{stem}.cast" title="{alt}"></div>\n\n'
            f"<noscript>{match.group(0)}</noscript>"
        )

    return GIF.sub(replace, markdown)
